import { Fragment, type ReactNode } from 'react';
// Small renderer for the study reports (headings, paragraphs, lists, tables, **bold**, `code`).
// The text is generated by the project, so no HTML is parsed: everything is rendered as React text.
function inline(text:string):ReactNode[]{
 return text.split(/(\*\*[^*]+\*\*|`[^`]+`)/g).filter(Boolean).map((part,i)=>part.startsWith('**')?<b key={i}>{part.slice(2,-2)}</b>:part.startsWith('`')?<code key={i}>{part.slice(1,-1)}</code>:<Fragment key={i}>{part}</Fragment>);
}
const cells=(line:string)=>line.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim());
export function MarkdownReport({text}:{text:string}){
 const lines=text.replace(/\r/g,'').split('\n'),out:ReactNode[]=[];
 let i=0;
 while(i<lines.length){
  const line=lines[i];
  if(!line.trim()){i++;continue;}
  const h=/^(#{1,4})\s+(.*)$/.exec(line);
  if(h){const level=h[1].length;const T=(level<=1?'h2':level===2?'h3':'h4') as 'h2'|'h3'|'h4';out.push(<T key={i}>{inline(h[2])}</T>);i++;continue;}
  if(line.trim().startsWith('|')){
   const rows:string[]=[];while(i<lines.length&&lines[i].trim().startsWith('|'))rows.push(lines[i++]);
   const body=rows.slice(rows.length>1&&/^\s*\|?\s*:?-+/.test(rows[1])?2:1);
   out.push(<div key={i} className="report-table"><table><thead><tr>{cells(rows[0]).map((c,k)=><th key={k}>{inline(c)}</th>)}</tr></thead><tbody>{body.map((r,j)=><tr key={j}>{cells(r).map((c,k)=><td key={k}>{inline(c)}</td>)}</tr>)}</tbody></table></div>);continue;
  }
  if(/^\s*([-*]|\d+\.)\s+/.test(line)){
   const ordered=/^\s*\d+\./.test(line),items:string[]=[];
   while(i<lines.length&&/^\s*([-*]|\d+\.)\s+/.test(lines[i])){let item=lines[i++].replace(/^\s*([-*]|\d+\.)\s+/,'');while(i<lines.length&&/^\s{2,}\S/.test(lines[i])&&!/^\s*([-*]|\d+\.)\s+/.test(lines[i]))item+=' '+lines[i++].trim();items.push(item);}
   const L=ordered?'ol':'ul';out.push(<L key={i}>{items.map((t,k)=><li key={k}>{inline(t)}</li>)}</L>);continue;
  }
  const para:string[]=[];while(i<lines.length&&lines[i].trim()&&!/^(#{1,4}\s|\s*\||\s*([-*]|\d+\.)\s+)/.test(lines[i]))para.push(lines[i++].trim());
  out.push(<p key={i}>{inline(para.join(' '))}</p>);
 }
 return <div className="markdown-report">{out}</div>;
}
